<script setup lang="ts">
import {onMounted,reactive,ref} from 'vue'
import type {PayChange} from '../payChanges'
import {WorkforceApiError} from '../api'
import PayTemplateUpgrade from '../components/PayTemplateUpgrade.vue'
import {usePayrollPage} from '../payrollPage'
import {blankRule,copy,validRule} from '../payrollUi'
import type {Option,StoreOption} from '../types'
import type {TemplateMaster,TemplateLibraryEntry,TemplatePreview,TemplateDraftForm} from '../payTemplatePublication'
import ScheduledPayAdoptions from '../components/ScheduledPayAdoptions.vue'
import PhaseStatus from '../components/PhaseStatus.vue'
import PayTemplateMasterEditor from '../components/PayTemplateMasterEditor.vue'
import PayTemplateReleasePreview from '../components/PayTemplateReleasePreview.vue'
const {base,home,api,english,loading,busy,failure,notice,load,write}=usePayrollPage(),x=(zh:string,en:string)=>english()?en:zh
const masters=ref<TemplateMaster[]>([]),entries=ref<TemplateLibraryEntry[]>([]),draft=ref<TemplateDraftForm|null>(null),preview=ref<TemplatePreview|null>(null),versions=reactive<Record<string,number>>({})
const publicationOpen=ref(false)
const upgrading=ref(false),savedUpgrade=ref<PayChange|null>(null)
const publicationCompanies=ref<Option[]>([]),publicationStores=ref<StoreOption[]>([])
const publishCommands=new Map<string,string>();let enableCommand=''
function refresh(){return load(async()=>{const [library,list,directory]=await Promise.all([api().get<TemplateLibraryEntry[]>('/pay-template-library'),home.value?.headOffice?api().get<TemplateMaster[]>('/pay-template-masters'):Promise.resolve([]),home.value?.headOffice?api().get<{companies:Option[];stores:StoreOption[]}>('/pay-template-publication-directory'):Promise.resolve({companies:[],stores:[]})]);return {library,list,directory}},v=>{entries.value=v.library;masters.value=v.list;publicationCompanies.value=v.directory.companies||[];publicationStores.value=v.directory.stores||[];for(const entry of v.library)versions[entry.masterId]=entry.latestReleaseVersion})}
function edit(master?:TemplateMaster){publicationOpen.value=true;draft.value=master?{...copy(master),expectedVersion:master.version}:{id:crypto.randomUUID(),expectedVersion:0,name:'',rule:blankRule(),companyIds:[],storeIds:[],includeFutureStores:false}}
function save(){const d=draft.value;if(!d)return;const legal=publicationStores.value.filter(s=>s.companyId&&d.companyIds.includes(s.companyId)).map(s=>s.id);if(d.storeIds.some(id=>!legal.includes(id))||!d.name.trim()||!validRule(d.rule)||!d.companyIds.length||(!d.storeIds.length&&!d.includeFutureStores)){failure.value=x('请填写合法规则、公司与适用门店范围。','Enter valid rules, companies and store scope.');return}return write(()=>api().put('/pay-template-masters/'+d.id,{expectedVersion:d.expectedVersion,name:d.name.trim(),rule:d.rule,companyIds:d.companyIds,storeIds:d.storeIds,includeFutureStores:d.includeFutureStores}),async()=>{draft.value=null;await refresh()})}
function publish(master:TemplateMaster){const key=master.id+':'+master.version;let command=publishCommands.get(key);if(!command){command=crypto.randomUUID();publishCommands.set(key,command)}return write(()=>api().put('/pay-template-masters/'+master.id+'/publish',{commandId:command,expectedDraftVersion:master.version}),async()=>{await refresh()})}
function show(entry:TemplateLibraryEntry){preview.value=null;upgrading.value=false;savedUpgrade.value=null;enableCommand='';return load(()=>api().get<TemplatePreview>('/pay-template-library/'+entry.masterId+'/preview?releaseVersion='+versions[entry.masterId]),v=>{preview.value=v;enableCommand=crypto.randomUUID()})}
function enable(){const p=preview.value;if(!p||p.scheduledAdoptions?.length)return;return write(()=>api().put('/pay-template-library/'+p.release.masterId+'/enable',{commandId:enableCommand,releaseVersion:p.release.version,expectedAdoptionVersion:p.adoption?.storeVersion||0}),async()=>{preview.value=null;await refresh()},e=>{if(e instanceof WorkforceApiError&&e.code==='WORKFORCE_PAYROLL_TEMPLATE_UPGRADE_REQUIRED'){upgrading.value=true;notice.value=x('本店有经济修改，请读取三方差异并保存升级申请。','Local changes require a three-way upgrade request.');return true}return false})}
const state=(value:string)=>value==='available'?x('可用 · 尚未启用','Available · not enabled'):value==='updateAvailable'?x('有新版本 · 当前采用保持固定','Update available · current adoption stays fixed'):x('已启用','Enabled')
onMounted(()=>void refresh())
</script>
<template><section v-if="home?.employeeManage||home?.headOffice" class="wf-panel"><header class="wf-toolbar"><h2>{{x('门店模板库','Store template library')}}</h2><button type="button" :disabled="loading||busy" @click="refresh">{{x('刷新','Refresh')}}</button></header><RouterLink class="wf-button" :to="base+'/pay-change-requests'">{{x('本店派生申请与审批','Store derivation requests and review')}}</RouterLink><p class="wf-hint">{{x('模板可见和启用不授予个人工资读取权。原公司共享模板仍从工资设置中维护。','Template visibility and enable do not grant personal salary access. Legacy company templates remain in payroll settings.')}}</p><PhaseStatus :failure="failure" :notice="notice" :loading="loading"/><template v-if="!loading"><p v-if="!entries.length&&!failure" class="wf-empty">{{x('暂无适用的已发布模板。','No applicable published templates.')}}</p><div v-else-if="entries.length" class="wf-table-wrap"><table><thead><tr><th>{{x('名称','Name')}}</th><th>{{x('状态','State')}}</th><th>{{x('固定版本','Fixed version')}}</th><th></th></tr></thead><tbody><tr v-for="entry in entries" :key="entry.masterId"><td>{{entry.name}}</td><td>{{state(entry.state)}}<span v-if="entry.adoption"> · {{entry.adoption.releaseVersion}} / {{entry.adoption.storeVersion}}</span><ScheduledPayAdoptions :items="entry.scheduledAdoptions"/></td><td><input v-model.number="versions[entry.masterId]" type="number" min="1" :max="entry.latestReleaseVersion" :aria-label="x('预览发布版本','Preview release version')"></td><td><button type="button" :disabled="busy" @click="show(entry)">{{x('预览','Preview')}}</button></td></tr></tbody></table></div></template><PayTemplateUpgrade v-if="upgrading&&preview" :adoptions="[...(preview.adoption?[preview.adoption]:[]),...(preview.scheduledAdoptions||[]).map(s=>s.adoption)]" :adoption-dates="Object.fromEntries((preview.scheduledAdoptions||[]).map(s=>[s.adoption.id,s.effectiveDate]))" :target-version="preview.release.version" @close="upgrading=false" @saved="savedUpgrade=$event;upgrading=false;preview=null"/><p v-if="savedUpgrade" class="wf-hint">{{x('升级草稿已保存，继续提交审批。','Upgrade draft saved; continue submission and review.')}} <RouterLink :to="base+'/pay-change-requests?companyId='+savedUpgrade.companyId+'&requestId='+savedUpgrade.id">{{x('继续提交审批','Continue submission and review')}}</RouterLink></p><PayTemplateReleasePreview v-if="preview&&!upgrading" :preview="preview" :companies="home.companies" :stores="home.stores" :busy="busy||loading" @enable="enable" @upgrade="upgrading=true" @close="preview=null"/><details v-if="home.headOffice" class="wf-task-section" :open="publicationOpen" @toggle="publicationOpen=($event.target as HTMLDetailsElement).open"><summary>{{x('总部：创建、保存与发布母版','Head office: create, save and publish masters')}}</summary><p class="wf-hint">{{x('保存草稿 → 发布已保存版本 → 门店预览并启用。只保存或发布，不会替门店启用，也不会覆盖员工工资。','Save draft → publish saved version → store previews and enables. Saving or publishing does not enable a store or overwrite employee pay.')}}</p><header class="wf-toolbar"><h3>{{x('租户母版发布','Tenant master publication')}}</h3><button type="button" :disabled="busy" @click="edit()">{{x('新建母版','New master')}}</button></header><article v-for="master in masters" :key="master.id" class="wf-toolbar"><span>{{master.name}} · {{x('草稿版本','Draft version')}} {{master.version}}</span><button type="button" :disabled="busy" @click="edit(master)">{{x('编辑草稿','Edit draft')}}</button><button type="button" :disabled="busy" @click="publish(master)">{{x('发布已保存版本','Publish saved version')}}</button></article><PayTemplateMasterEditor v-if="draft" :draft="draft" :companies="publicationCompanies" :stores="publicationStores" :busy="busy" @save="save" @cancel="draft=null"/></details></section><p v-else role="alert">{{x('无门店模板管理权限。','Store template management access required.')}}</p></template>
